	["Obsidian"] = "Obsidian", -- draft
	["Neutral black glass and pewter, cold white text, one crimson accent. The calmest, highest-contrast base."] = "Cristal negro neutro y peltre, texto blanco frío, un acento carmesí. La base más tranquila y con más contraste.", -- draft
	["Obsidian Vibrant"] = "Obsidian Vibrant", -- draft
