	["Frame, background and segment dividers of the experience, reputation and honor bars."] = "Marco, fondo y divisores de segmentos de las barras de experiencia, reputación y honor.", -- draft
	["Cooldown Manager"] = "Gestor de tiempos de reutilización", -- draft
	["Icon frames and bar backgrounds of the Essential, Utility and Buff cooldown viewers."] = "Los marcos de icono y los fondos de barra de los visores de tiempos de reutilización esenciales, de utilidad y de beneficios.", -- draft
