	["Values Font"] = "Fuente de los valores", -- draft
	["The face of the health and power values on the player, target and focus frames. Shared: the Interface text's face (Look > Fonts)."] = "La fuente de los valores de salud y recurso en los marcos de jugador, objetivo y foco. Compartida: la fuente del Texto de la interfaz (Aspecto > Fuentes).", -- draft
