	-- CooldownText
	["Cooldown Timers"] = "Temporizadores de reutilización", -- draft
	["Large countdown numbers on action bar cooldowns and nameplate auras, coloured by time left."] = "Grandes números de cuenta atrás en los tiempos de reutilización de las barras de acción y en las auras de las placas de nombre, coloreados según el tiempo restante.", -- draft
	["Countdowns on every cooldown, coloured by how long you still have to wait."] = "Cuentas atrás en cada tiempo de reutilización, coloreadas según cuánto te queda por esperar.", -- draft
	["Countdown numbers on action bar cooldowns and nameplate auras, coloured by the time left."] = "Números de cuenta atrás en los tiempos de reutilización de las barras de acción y en las auras de las placas de nombre, coloreados según el tiempo restante.", -- draft
	["Show On"] = "Mostrar en", -- draft
	["Action, pet, stance and flyout buttons."] = "Botones de acción, de mascota, de actitud y desplegables.", -- draft
	["Nameplate Auras"] = "Auras de placas de nombre", -- draft
	["Buff, debuff and crowd control icons on nameplates. While Buffs & Debuffs puts your debuffs on enemy nameplates, those icons are MelloUI's own and show their own time: this switch does not reach them."] = "Iconos de beneficios, perjuicios y control de masas en las placas de nombre. Mientras Beneficios y perjuicios pone tus perjuicios en las placas de nombre enemigas, esos iconos son de MelloUI y muestran su propio tiempo: este interruptor no los alcanza.", -- draft
	["Timer"] = "Temporizador", -- draft
	["Minimum Duration"] = "Duración mínima", -- draft
	["Cooldowns shorter than this show no text (2 s skips the global cooldown)."] = "Los tiempos de reutilización más cortos que esto no muestran texto (2 s omite el tiempo de reutilización global).", -- draft
	["Text Size"] = "Tamaño del texto", -- draft
	["Text height relative to the icon size."] = "Altura del texto respecto al tamaño del icono.", -- draft
	["Show Tenths Below 5s"] = "Décimas por debajo de 5 s", -- draft
	["Show 4.3 instead of 5 when the cooldown is about to finish."] = "Muestra 4.3 en lugar de 5 cuando el tiempo de reutilización está a punto de acabar.", -- draft
	["Colour And Size By Time Left"] = "Color y tamaño según el tiempo restante", -- draft
	["Red and larger under 5 s (1.3 times the Text Size), yellow under a minute, dim white and smaller for minutes (0.8 times), grey and smaller still for hours (0.75 times). Off: every timer is white at the Text Size."] = "Rojo y más grande por debajo de 5 s (1,3 veces el Tamaño del texto), amarillo por debajo de un minuto, blanco tenue y más pequeño para minutos (0,8 veces), gris y aún más pequeño para horas (0,75 veces). Desactivado: todos los temporizadores son blancos al Tamaño del texto.", -- draft
	-- Tweaks
	["Tweaks"] = "Ajustes", -- draft
	["Hide the micro menu and bag bar, and scale the floating combat text."] = "Oculta el micromenú y la barra de bolsas, y escala el texto de combate flotante.", -- draft
	["Small knobs with a big effect. Hide what you never click, scale what you never see."] = "Pequeños mandos con gran efecto. Oculta lo que nunca pulsas, escala lo que nunca ves.", -- draft
	["Hide Frames"] = "Ocultar marcos", -- draft
	["Hide Micro Menu"] = "Ocultar micromenú", -- draft
	["Hide the row of menu buttons (character, spellbook, talents, ...). Still shown while Edit Mode is open."] = "Oculta la fila de botones de menú (personaje, libro de hechizos, talentos, ...). Se sigue viendo mientras el Modo edición está abierto.", -- draft
	["Hide Bag Bar"] = "Ocultar barra de bolsas", -- draft
	["Hide the backpack and bag slot buttons. Still shown while Edit Mode is open. Bags can still be opened with their keybinds."] = "Oculta los botones de la mochila y de las casillas de bolsa. Se sigue viendo mientras el Modo edición está abierto. Las bolsas se pueden seguir abriendo con sus atajos.", -- draft
	["Hide Minimap Coordinates"] = "Ocultar coordenadas del minimapa", -- draft
	["Hide the player coordinates the client writes under the minimap."] = "Oculta las coordenadas del jugador que el cliente escribe bajo el minimapa.", -- draft
	["Bag Slots On Bag Window"] = "Casillas de bolsa en la ventana de bolsas", -- draft
	["While the bag bar is hidden, show the bag slots under the open bag window so bags can still be equipped and removed. Works with and without the Combine Bags option."] = "Mientras la barra de bolsas está oculta, muestra las casillas de bolsa bajo la ventana de bolsa abierta para poder seguir equipando y quitando bolsas. Funciona con y sin la opción Combinar bolsas.", -- draft
	["Collapse Arrow"] = "Flecha de plegado", -- draft
	["An arrow beside the backpack folds the bag slots away so only the backpack shows; click it again to bring them back. While you hold an item they come out by themselves, so a new bag can be dropped into a slot. The game remembers which way you left it."] = "Una flecha junto a la mochila pliega las casillas de bolsa para que solo se vea la mochila; púlsala otra vez para que vuelvan. Mientras sostienes un objeto salen solas, para poder soltar una bolsa nueva en una casilla. El juego recuerda cómo la dejaste.", -- draft
	["Chat"] = "Chat", -- draft
	["Chat Notices"] = "Avisos en el chat", -- draft
	["Lines MelloUI writes to chat on its own: a learned dungeon entrance, settings restored from the backup, hints. Replies to slash commands, and the notices you send to the chat (Send To Chat Instead), always show."] = "Líneas que MelloUI escribe en el chat por su cuenta: una entrada de mazmorra aprendida, ajustes restaurados de la copia de seguridad, consejos. Las respuestas a comandos con barra y los avisos que envías al chat (Enviar al chat) siempre se muestran.", -- draft
	["Notices"] = "Avisos", -- draft
	["On-screen Notices"] = "Avisos en pantalla", -- draft
	["One short line in the upper third of the screen when MelloUI has news for you: a route set or finished, a service remembered, a dungeon's quests listed. It fades after a few seconds. Move it in Edit Layout."] = "Una línea corta en el tercio superior de la pantalla cuando MelloUI tiene novedades para ti: una ruta fijada o terminada, un servicio recordado, las misiones de una mazmorra listadas. Se desvanece tras unos segundos. Muévela en Editar diseño.", -- draft
	["Send To Chat Instead"] = "Enviar al chat", -- draft
	["Write these lines in the chat instead of showing them on the screen. They show there even while Chat Notices is off."] = "Escribe estas líneas en el chat en lugar de mostrarlas en pantalla. Aparecen allí aunque Avisos en el chat esté desactivado.", -- draft
	["Notice Sounds"] = "Sonidos de aviso", -- draft
	["A short chime with each notice: the map's tracking sound for a new destination (left out while the World Marker's own sound plays for it), a softer one when you arrive."] = "Un breve tintineo con cada aviso: el sonido de rastreo del mapa para un nuevo destino (se omite mientras suena el propio sonido del Marcador del mundo), uno más suave al llegar.", -- draft
	["Text Shade"] = "Sombra del texto", -- draft
	["A soft dark shade behind the text MelloUI shows on the world, so it reads on bright ground: the zone name when you enter a new area (with its subzone and PvP lines), the game's messages in the middle of the screen (red errors, yellow quest progress, raid warnings and boss emotes), the Route's World Marker, the names on the unit frames (yours, your pet's, your targets' targets' and the party's) and on the nameplates, and the channel tags and links on the chat's parchment. No outline on the zone name and the messages (Outlined Text adds it back); the game's colours stay. Off: the game's own look, and no shade behind any of them."] = "Una sombra suave y oscura tras el texto que MelloUI muestra sobre el mundo, para que se lea sobre fondos claros: el nombre de zona al entrar en una zona nueva (con sus líneas de subzona y JcJ), los mensajes del juego en el centro de la pantalla (errores rojos, progreso de misión amarillo, alertas de banda y emociones de jefe), el Marcador del mundo de la Ruta, los nombres en los marcos de unidad (el tuyo, el de tu mascota, los de los objetivos de tus objetivos y el grupo) y en las placas de nombre, y las etiquetas de canal y enlaces en el pergamino del chat. Sin contorno en el nombre de zona y los mensajes (Texto con contorno lo devuelve); los colores del juego se mantienen. Desactivado: el aspecto del juego, y ninguna sombra tras ellos.", -- draft
	["Outlined Text"] = "Texto con contorno", -- draft
	["Draw the text MelloUI shows on the world with an outline: the on-screen notice's lines, Combat Text's lines and the Gains lines, and, while Text Shade is on, the zone text and the game's messages in the middle of the screen. Off: soft text on a dark shade."] = "Dibuja con contorno el texto que MelloUI muestra sobre el mundo: las líneas del aviso en pantalla, las del Texto de combate y las líneas de ganancias, y, mientras Sombra del texto está activa, el texto de zona y los mensajes del juego en el centro de la pantalla. Desactivado: texto suave sobre una sombra oscura.", -- draft
	["Combat Text"] = "Texto de combate", -- draft
	["Numbers Over Enemies"] = "Números sobre los enemigos", -- draft
	["The size of the numbers over the enemies and the ones you heal: the game's own, and Your Damage's when MelloUI draws them (one or the other shows). 1.0 is the game's size."] = "El tamaño de los números sobre los enemigos y sobre quienes sanas: los del juego, y los de Tu daño cuando MelloUI los dibuja (se ve uno u otro). 1.0 es el tamaño del juego.", -- draft
	["Bar Layout"] = "Diseño de barras", -- draft
	["Which Bar"] = "Qué barra", -- draft
	["The bar the rows below set: its rows, icons, icon size and padding, saved into your active Edit Mode layout as Edit Mode saves them, once you let a slider go (out of combat). The game shows them after a reload: type /reload (MelloUI says so once). One of the game's preset layouts is copied first: you are asked once."] = "La barra que ajustan las filas de abajo: sus filas, iconos, tamaño de icono y separación, guardados en tu diseño activo del Modo edición como los guarda el Modo edición, en cuanto sueltas un deslizador (fuera de combate). El juego los muestra tras recargar: escribe /reload (MelloUI lo dice una vez). Primero se copia uno de los diseños predefinidos del juego: se te pregunta una vez.", -- draft
	["Action Bar 1"] = "Barra de acción 1", -- draft
	["Action Bar 2"] = "Barra de acción 2", -- draft
	["Action Bar 3"] = "Barra de acción 3", -- draft
	["Action Bar 4"] = "Barra de acción 4", -- draft
	["Action Bar 5"] = "Barra de acción 5", -- draft
	["Action Bar 6"] = "Barra de acción 6", -- draft
	["Action Bar 7"] = "Barra de acción 7", -- draft
	["Action Bar 8"] = "Barra de acción 8", -- draft
	["Stance Bar"] = "Barra de actitudes", -- draft
	["Pet Bar"] = "Barra de mascota", -- draft
	["Rows"] = "Filas", -- draft
	["How many rows the bar's buttons stand in (columns, on a bar stood upright in Edit Mode)."] = "En cuántas filas se colocan los botones de la barra (columnas, en una barra puesta en vertical en el Modo edición).", -- draft
	["Icons"] = "Iconos", -- draft
	["How many of the bar's buttons show."] = "Cuántos botones de la barra se muestran.", -- draft
	["Icon Size"] = "Tamaño de icono", -- draft
	["The size of the bar's buttons. 100% is the game's own size."] = "El tamaño de los botones de la barra. 100% es el tamaño del juego.", -- draft
	["Padding"] = "Separación", -- draft
	["The room between the bar's buttons."] = "El espacio entre los botones de la barra.", -- draft
	["The Bar's Shape"] = "La forma de la barra", -- draft
	["The bar as the rows above lay it out. Saved into your Edit Mode layout when you let a slider go (in a fight, when it ends); the bar itself changes after a reload."] = "La barra tal como la disponen las filas de arriba. Se guarda en tu diseño del Modo edición al soltar un deslizador (en combate, cuando termina); la barra en sí cambia tras recargar.", -- draft
	["Buff Layout"] = "Diseño de beneficios", -- draft
	["The size of your buff and debuff icons, in pixels: MelloUI's own rows while Your Buffs And Debuffs shows them, else the game's buff and debuff bars (saved into your Edit Mode layout in its own steps of 3 pixels, shown after a reload; 30 is the game's size)."] = "El tamaño de tus iconos de beneficios y perjuicios, en píxeles: las filas de MelloUI mientras Tus beneficios y perjuicios las muestra; si no, las barras de beneficios y perjuicios del juego (guardado en tu diseño del Modo edición en pasos de 3 píxeles, visible tras recargar; 30 es el tamaño del juego).", -- draft
	["Spacing"] = "Espaciado", -- draft
	["The room between your buff and debuff icons."] = "El espacio entre tus iconos de beneficios y perjuicios.", -- draft
	["Per Row"] = "Por fila", -- draft
	["How many buffs stand in a row before the next row starts. Your debuffs start a row of their own (the game's debuff bar takes at most 16 in a row)."] = "Cuántos beneficios caben en una fila antes de empezar la siguiente. Tus perjuicios empiezan su propia fila (la barra de perjuicios del juego admite como mucho 16 por fila).", -- draft
	["Grow"] = "Crecer", -- draft
	["Which way a row of buffs grows from the first one."] = "Hacia dónde crece una fila de beneficios desde el primero.", -- draft
	["New Rows"] = "Filas nuevas", -- draft
	["Where the next row of buffs goes: under the first, or over it."] = "Dónde va la siguiente fila de beneficios: debajo de la primera o encima.", -- draft
	["Down"] = "Abajo", -- draft
	["Up"] = "Arriba", -- draft
	["Split Stack"] = "Dividir montón", -- draft
	["Mouse Wheel Amount"] = "Cantidad con la rueda", -- draft
	["In the box that splits a stack (Shift-click a stack), the mouse wheel changes the amount: up adds one, down takes one, ten at a time while you hold Shift."] = "En la caja que divide un montón (Mayús-clic en un montón), la rueda del ratón cambia la cantidad: arriba suma uno, abajo quita uno, de diez en diez mientras mantienes Mayús.", -- draft
	["Half Button"] = "Botón de mitad", -- draft
	["A ½ button at the left end of the split box's amount: click it and the amount is half the stack (191 makes 95). Buying in bundles at a merchant, it rounds down to whole bundles."] = "Un botón ½ al extremo izquierdo de la cantidad de la caja de dividir: púlsalo y la cantidad es la mitad del montón (191 da 95). Al comprar por lotes en un mercader, redondea hacia abajo a lotes enteros.", -- draft
	["Item Slots"] = "Casillas de objeto", -- draft
	["Quality Gems"] = "Gemas de calidad", -- draft
	["A small gem in the top-left corner of every item in your bags, the bank and the guild bank, in the colour of the item's quality: grey for junk, white for common, then green, blue, purple and orange. Junk and better items stand out at a glance. While the game shows its own mark in that corner (the junk coin at a merchant, the upgrade arrow, the exclamation mark on an item that starts a quest, the quality badge on a crafting reagent), the gem moves to the top-right corner. One switch for all three windows."] = "Una pequeña gema en la esquina superior izquierda de cada objeto de tus bolsas, del banco y del banco de hermandad, del color de la calidad del objeto: gris para la chatarra, blanco para lo común, luego verde, azul, morado y naranja. La chatarra y los mejores objetos destacan de un vistazo. Mientras el juego muestra su propia marca en esa esquina (la moneda de chatarra en un mercader, la flecha de mejora, el signo de exclamación de un objeto que inicia una misión, la insignia de calidad de un componente de fabricación), la gema pasa a la esquina superior derecha. Un interruptor para las tres ventanas.", -- draft
	["Grey Out Junk"] = "Atenuar la chatarra", -- draft
	["Junk (grey quality) items show grey in your bags, the bank and the guild bank, so they stand apart from what you keep. One switch for all three windows."] = "Los objetos de chatarra (calidad gris) se ven grises en tus bolsas, el banco y el banco de hermandad, para que se distingan de lo que guardas. Un interruptor para las tres ventanas.", -- draft
	["Level Up"] = "Subida de nivel", -- draft
	["When you gain a level, a light runs along the experience bar and the on-screen notice says your new level and, with the Quest List, how many quests it opened in your zone (their givers pop onto the world map the next time it shows them). With the painted reskin, the number in your player frame's level circle also turns over with a ring of light. Not with Reduce Motion: then only the notice."] = "Al subir de nivel, una luz recorre la barra de experiencia y el aviso en pantalla dice tu nuevo nivel y, con la Lista de misiones, cuántas misiones abrió en tu zona (sus dadores aparecen en el mapa del mundo la próxima vez que los muestre). Con el aspecto pintado, el número del círculo de nivel de tu marco de jugador también gira con un anillo de luz. No con Reducir movimiento: entonces solo el aviso.", -- draft
	["XP Gain"] = "Ganancia de experiencia", -- draft
	["When you gain experience, the stretch of the experience bar just gained lights up while a light runs along it to the new end. Not with Reduce Motion."] = "Al ganar experiencia, el tramo de la barra de experiencia recién ganado se ilumina mientras una luz la recorre hasta el nuevo final. No con Reducir movimiento.", -- draft
	-- Stats
	["Small coloured FPS and latency readout in the bottom right corner."] = "Pequeño indicador de colores de FPS y latencia en la esquina inferior derecha.", -- draft
	["Frames per second and latency in the corner. Blame the server with confidence."] = "Fotogramas por segundo y latencia en la esquina. Culpa al servidor con confianza.", -- draft
	["Values"] = "Valores", -- draft
	["Show FPS"] = "Mostrar FPS", -- draft
	["Frames per second."] = "Fotogramas por segundo.", -- draft
	["Show Latency"] = "Mostrar latencia", -- draft
	["Home latency in milliseconds."] = "Latencia local en milisegundos.", -- draft
	["Show World Latency Too"] = "Mostrar también la latencia del mundo", -- draft
	["Also show the world server latency next to the home latency."] = "Muestra también la latencia del servidor del mundo junto a la latencia local.", -- draft
	["Look"] = "Aspecto", -- draft
	["Distance from the right edge of the screen."] = "Distancia desde el borde derecho de la pantalla.", -- draft
	["Distance from the bottom edge of the screen."] = "Distancia desde el borde inferior de la pantalla.", -- draft
	["Update Interval"] = "Intervalo de actualización", -- draft
	-- Vendor
	["Vendor"] = "Mercader", -- draft
	["Automatically repair your gear and sell junk items when visiting a merchant."] = "Repara tu equipo y vende la chatarra automáticamente al visitar a un mercader.", -- draft
	["Sell the grey, mend the steel. Every merchant visit handled before the window opens."] = "Vende lo gris, repara el acero. Cada visita al mercader resuelta antes de que se abra la ventana.", -- draft
	["Repair"] = "Reparación", -- draft
	["Auto Repair"] = "Reparación automática", -- draft
	["Repair all equipped and carried items when a merchant that can repair is opened."] = "Repara todos los objetos equipados y llevados al abrir un mercader que pueda reparar.", -- draft
	["Use Guild Funds"] = "Usar fondos de hermandad", -- draft
	["Pay repairs from the guild bank when allowed. Falls back to your own gold if the guild cannot cover the cost."] = "Paga las reparaciones con el banco de hermandad cuando esté permitido. Si la hermandad no puede cubrir el coste, usa tu propio oro.", -- draft
	["Selling"] = "Venta", -- draft
	["Auto Sell Junk"] = "Vender chatarra automáticamente", -- draft
	["Sell all grey quality items in your bags when a merchant is opened."] = "Vende todos los objetos de calidad gris de tus bolsas al abrir un mercader.", -- draft
	["Report In Chat"] = "Informar en el chat", -- draft
	["Print the repair cost, the gold gained from selling junk and what Restock bought for you."] = "Escribe el coste de reparación, el oro ganado vendiendo chatarra y lo que Reabastecer compró por ti.", -- draft
	-- Services
	["Services"] = "Servicios", -- draft
	["Service icons under the minimap that route you to the nearest repair, mailbox, innkeeper, flight master, auction house, bank, trainer, barber or transmogrifier."] = "Iconos de servicio bajo el minimapa que te guían a la reparación, buzón, tabernero, maestro de vuelo, casa de subastas, banco, instructor, peluquero o transfigurador más cercano.", -- draft
	["Repair, mailbox, innkeeper, bank... the nearest one is a click under the minimap."] = "Reparación, buzón, tabernero, banco... el más cercano está a un clic bajo el minimapa.", -- draft
	["Icon Bar Under The Minimap"] = "Barra de iconos bajo el minimapa", -- draft
	["Service buttons under the minimap; they move with the minimap in Edit Mode. Groups: one row of group buttons as wide as the map; click one to open its services with their distances, then click a service to route to the nearest one by road. All Buttons: two rows with an icon for every service; click one to route there. Right-click stops the route. A grey button has none known on this continent yet. With the square minimap and \"Merge With Services\" on (the Minimap page, Services), the buttons sit inside the minimap's frame."] = "Botones de servicio bajo el minimapa; se mueven con el minimapa en el Modo edición. Grupos: una fila de botones de grupo tan ancha como el mapa; pulsa uno para abrir sus servicios con sus distancias, y luego un servicio para una ruta por camino al más cercano. Todos los botones: dos filas con un icono por servicio; pulsa uno para una ruta. Clic derecho detiene la ruta. Un botón gris aún no conoce ninguno en este continente. Con el minimapa cuadrado y «Unir con servicios» activo (página Minimapa, Servicios), los botones se colocan dentro del marco del minimapa.", -- draft
	["Button Layout"] = "Disposición de botones", -- draft
	["Groups: one row of buttons as wide as the map (Travel, Trade, Repair, Trainers, Looks, Errands, and AddOns while your addons have minimap buttons). Click a group for a small list of its services, each with the distance to the nearest one; click a service to route there. Repair routes at once. Errands lists your reminders (Restock, Mail, Repair Gear, Trainer) and how each stands; click one to route to the nearest place for it. All Buttons: two rows with an icon for every service."] = "Grupos: una fila de botones tan ancha como el mapa (Viaje, Comercio, Reparación, Instructores, Apariencias, Recados, y Addons mientras tus addons tengan botones de minimapa). Pulsa un grupo para una pequeña lista de sus servicios, cada uno con la distancia al más cercano; pulsa un servicio para una ruta. Reparación traza la ruta al instante. Recados lista tus recordatorios (Reabastecer, Correo, Reparar equipo, Instructor) y cómo está cada uno; pulsa uno para una ruta al lugar más cercano. Todos los botones: dos filas con un icono por servicio.", -- draft
	["Groups"] = "Grupos", -- draft
	["All Buttons"] = "Todos los botones", -- draft
	["AddOns Group"] = "Grupo Addons", -- draft
	["Your addons' minimap buttons (Questie and the others that put a round button on the minimap's edge) taken off the minimap and gathered into one more group in the Services row, AddOns: click it for a list of them. A click on an addon there is that addon's own (left, right or middle), and pointing at it shows its own tooltip. Only with Button Layout's Groups. Off: the buttons go back on the minimap."] = "Los botones de minimapa de tus addons (Questie y los demás que ponen un botón redondo en el borde del minimapa) quitados del minimapa y reunidos en un grupo más de la fila Servicios, Addons: púlsalo para verlos en una lista. Un clic en un addon allí es el del propio addon (izquierdo, derecho o central), y señalarlo muestra su propia descripción. Solo con los Grupos de Disposición de botones. Desactivado: los botones vuelven al minimapa.", -- draft
	["Bar Distance From The Minimap"] = "Distancia de la barra al minimapa", -- draft
	["How far under the minimap the buttons sit. Not used while they are merged into the square minimap's frame."] = "A qué distancia bajo el minimapa se colocan los botones. No se usa mientras están unidos al marco del minimapa cuadrado.", -- draft
	["Round Icons"] = "Iconos redondos", -- draft
	["Show the service icons as round medallions in a round rim instead of squares."] = "Muestra los iconos de servicio como medallones redondos en un aro redondo en lugar de cuadrados.", -- draft
	["Trays Slide Out"] = "Las bandejas se deslizan", -- draft
	["A group's list slides out from the minimap column like a drawer when you click its button, its rows one after another, and slides back in as it closes. Not with Reduce Motion: then it shows at once."] = "La lista de un grupo sale de la columna del minimapa como un cajón al pulsar su botón, sus filas una tras otra, y vuelve a entrar al cerrarse. No con Reducir movimiento: entonces aparece al instante.", -- draft
	["Minimap Button"] = "Botón del minimapa", -- draft
	["Also show a round button on the minimap's edge that opens the list of the nearest services; drag it to move it, right-click it to stop the route. /services opens the same list."] = "Muestra también un botón redondo en el borde del minimapa que abre la lista de los servicios más cercanos; arrástralo para moverlo, clic derecho para detener la ruta. /services abre la misma lista.", -- draft
	-- Reminders
	["Reminders"] = "Recordatorios", -- draft
	["A round button by your portrait for errands: supplies low (Restock), new mail, gear to repair, a trainer with something new. Click it to route there. Off, none of the four shows; the Widgets' portrait reminders keep their own switches."] = "Un botón redondo junto a tu retrato para los recados: provisiones bajas (Reabastecer), correo nuevo, equipo por reparar, un instructor con algo nuevo. Púlsalo para una ruta. Desactivado, no se muestra ninguno de los cuatro; los recordatorios del retrato de los Widgets mantienen sus propios interruptores.", -- draft
	["Supplies, mail, repairs and training: a gentle nudge beside your portrait, never a nag."] = "Provisiones, correo, reparaciones y entrenamiento: un suave toque junto a tu retrato, nunca un sermón.", -- draft
	["New Mail"] = "Correo nuevo", -- draft
	["Remind you when mail is waiting for you. It goes once you open a mailbox, and comes back only for mail that arrives after."] = "Te avisa cuando tienes correo esperando. Se va al abrir un buzón y solo vuelve por correo que llegue después.", -- draft
	["Repair Gear"] = "Reparar equipo", -- draft
	["Remind you when your gear is wearing out. Broken gear goes to the top of the list."] = "Te avisa cuando tu equipo se está desgastando. El equipo roto pasa al principio de la lista.", -- draft
	["Remind At"] = "Avisar al", -- draft
	["Remind you once your most worn piece of gear is down to this much durability."] = "Te avisa cuando la pieza de equipo más gastada baja a esta durabilidad.", -- draft
	["Trainer"] = "Instructor", -- draft
	["Remind you when a trainer has something new for you."] = "Te avisa cuando un instructor tiene algo nuevo para ti.", -- draft
	["Class Spells"] = "Hechizos de clase", -- draft
	["When you reach a level with new spells at your class trainer. It stays until you have learned them; each visit to your class trainer tells MelloUI when the next ones come, and before your first visit it goes by the levels trainers teach at."] = "Cuando alcanzas un nivel con hechizos nuevos en tu instructor de clase. Se queda hasta que los aprendes; cada visita a tu instructor de clase le dice a MelloUI cuándo llegan los siguientes, y antes de tu primera visita se guía por los niveles en que enseñan los instructores.", -- draft
	["Profession Ranks"] = "Rangos de profesión", -- draft
	["When one of your professions can learn its next rank at a trainer: Journeyman, Expert or Artisan."] = "Cuando una de tus profesiones puede aprender su siguiente rango con un instructor: Oficial, Experto o Artesano.", -- draft
	["Stay Up In Rest Areas"] = "Mantener en zonas de descanso", -- draft
	["In an inn or a city, and in a town like Sentinel Hill, every reminder stays until it is done (a mailbox opened, the spells or the rank learned ...) or you leave; Not now there waits until you next enter one."] = "En una taberna o una ciudad, y en un pueblo como Colina del Centinela, cada recordatorio se queda hasta que se cumple (un buzón abierto, los hechizos o el rango aprendidos ...) o te vas; Ahora no allí espera hasta que vuelvas a entrar en una.", -- draft
	["Widget"] = "Widget", -- draft
	["Place"] = "Lugar", -- draft
	["Where the reminder button sits beside your portrait. With the player frame hidden it keeps a place of its own, which you can move in Edit Layout."] = "Dónde se coloca el botón de recordatorio junto a tu retrato. Con el marco de jugador oculto mantiene un lugar propio, que puedes mover en Editar diseño.", -- draft
	["Left of the portrait"] = "Izquierda del retrato", -- draft
	["Above the portrait"] = "Encima del retrato", -- draft
	["Right of the portrait"] = "Derecha del retrato", -- draft
	["Glow"] = "Brillo", -- draft
	["The soft glow around the button: a gentle pulse for a few seconds, then steady; always steady; or none. It brightens when you are close to where the reminder sends you."] = "El suave brillo alrededor del botón: un pulso suave unos segundos y luego fijo; siempre fijo; o ninguno. Se aviva cuando estás cerca de donde te envía el recordatorio.", -- draft
	["Pulse, then steady"] = "Pulso, luego fijo", -- draft
	["Steady"] = "Fijo", -- draft
	["Show For"] = "Mostrar durante", -- draft
	["How long a new reminder stays before it tucks itself away. It stays while your pointer is on it."] = "Cuánto tiempo se queda un recordatorio nuevo antes de recogerse. Se queda mientras tu puntero esté encima.", -- draft
	["Lock The Widgets"] = "Bloquear los widgets", -- draft
	["Keep the widget column (Voice Over, loot rolls, the corpse run and the rest) where it is: Edit Layout shows its plate but does not move it. Voice Over's padlock sets this too."] = "Mantiene la columna de widgets (Voice Over, tiradas de botín, el regreso al cadáver y el resto) donde está: Editar diseño muestra su placa pero no la mueve. El candado de Voice Over también ajusta esto.", -- draft
	["Most Widgets Shown"] = "Máximo de widgets visibles", -- draft
	["How many widgets the column shows at once. The rest wait in a slim \"+2 more\" row on top; a click there lists them. Loot rolls, summons, resurrect offers and ready checks always show, and Voice Over keeps the bottom place."] = "Cuántos widgets muestra la columna a la vez. El resto espera en una fina fila «+2 más» arriba; un clic los lista. Las tiradas de botín, invocaciones, ofertas de resurrección y comprobaciones de disposición siempre se muestran, y Voice Over conserva el lugar de abajo.", -- draft
	-- Restock
	["Restock"] = "Reabastecer", -- draft
	["Keeps drink, food, ammunition and reagents in your bags: a reminder when one runs low (with Reminders on), and at a shop a list of what to buy, bought only when you click Buy."] = "Mantiene bebida, comida, munición y componentes en tus bolsas: un aviso cuando algo escasea (con Recordatorios activo) y, en una tienda, una lista de qué comprar, comprado solo al pulsar Comprar.", -- draft
	["Water, bread and arrows, topped up before they run out."] = "Agua, pan y flechas, repuestos antes de que se acaben.", -- draft
	["Remind Below"] = "Avisar por debajo de", -- draft
	["You are reminded when a line drops below this share of its amount: at 50 %, a line of 20 water reminds you at 9. At a shop it is bought back up to the full amount. The reminder needs Reminders on; the Restock List marks the low lines either way."] = "Se te avisa cuando una línea baja de esta parte de su cantidad: al 50 %, una línea de 20 aguas te avisa en 9. En una tienda se vuelve a comprar hasta la cantidad completa. El aviso necesita Recordatorios activo; la Lista de reabastecimiento marca las líneas bajas igualmente.", -- draft
	["Shopping List At The Shop"] = "Lista de compra en la tienda", -- draft
	["At a merchant who sells what you are low on, a small list beside the shop window: each item, how many and the price, and the total. Nothing is bought until you click Buy."] = "En un mercader que vende lo que te falta, una pequeña lista junto a la ventana de la tienda: cada objeto, cuántos y el precio, y el total. No se compra nada hasta que pulsas Comprar.", -- draft
	["Restock List"] = "Lista de reabastecimiento", -- draft
	["What to keep in your bags and how many. Each character has its own list; a new one starts with suggestions for its class. Also /restock."] = "Qué guardar en tus bolsas y cuánto. Cada personaje tiene su propia lista; una nueva empieza con sugerencias para su clase. También /restock.", -- draft
	["Edit"] = "Editar", -- draft
	-- Widgets
	["Widgets"] = "Widgets", -- draft
	["Small live widgets in one column: loot rolls, the way back to your corpse, timed quests, summons, resurrect offers, ready checks, whispers, your pet, the auction house, crafting batches, profession cooldowns, quest items and a healer drinking. And more reminders by your portrait: bags, talents, Well Fed, weapon poisons and oils, your buffs."] = "Pequeños widgets en vivo en una columna: tiradas de botín, el camino de vuelta a tu cadáver, misiones con tiempo, invocaciones, ofertas de resurrección, comprobaciones de disposición, susurros, tu mascota, la casa de subastas, lotes de fabricación, tiempos de reutilización de profesión, objetos de misión y un sanador bebiendo. Y más recordatorios junto a tu retrato: bolsas, talentos, Bien alimentado, venenos y aceites de arma, tus beneficios.", -- draft
	["What needs you now, in one small column."] = "Lo que te necesita ahora, en una pequeña columna.", -- draft
	["In The Column"] = "En la columna", -- draft
	["Loot Rolls"] = "Tiradas de botín", -- draft
	["A roll in a group: the item in its quality colour, a ring for the time left, and Need, Greed and Pass on hover. The count is the rolls waiting. The game's own roll window stays out of sight meanwhile (with the Gamepad UI it stays)."] = "Una tirada en grupo: el objeto en el color de su calidad, un anillo para el tiempo restante y Necesidad, Codicia y Pasar al pasar el ratón. El número es el de tiradas pendientes. La ventana de tirada del juego queda oculta mientras tanto (con la interfaz de mando se queda).", -- draft
	["Corpse Run"] = "Regreso al cadáver", -- draft
	["As a ghost: how far your body is and which way, and a ring until you can come back. Click it for the way there; at your body, Resurrect. The game's own Resurrect popup is see-through and click-through meanwhile."] = "Como fantasma: a qué distancia está tu cuerpo y en qué dirección, y un anillo hasta que puedas volver. Púlsalo para ver el camino; junto a tu cuerpo, Resucitar. La ventana Resucitar del juego es transparente y deja pasar los clics mientras tanto.", -- draft
	["Timed Quests"] = "Misiones con tiempo", -- draft
	["A quest with a time limit: a ring for its whole time and the time left."] = "Una misión con límite de tiempo: un anillo para todo su tiempo y el tiempo restante.", -- draft
	["Summons"] = "Invocaciones", -- draft
	["Someone summons you: where to, the time left, and Accept or Decline on hover. The game's own popup is see-through and click-through meanwhile."] = "Alguien te invoca: a dónde, el tiempo restante y Aceptar o Rechazar al pasar el ratón. La ventana del juego es transparente y deja pasar los clics mientras tanto.", -- draft
	["Resurrect Offers"] = "Ofertas de resurrección", -- draft
	["Someone offers to resurrect you: the time left, and Accept or Decline on hover. The game's own popup is see-through and click-through meanwhile."] = "Alguien se ofrece a resucitarte: el tiempo restante y Aceptar o Rechazar al pasar el ratón. La ventana del juego es transparente y deja pasar los clics mientras tanto.", -- draft
	["Ready Checks"] = "Comprobaciones de disposición", -- draft
	["The leader's ready check and its time, with Ready and Not Ready on hover (a click on it: Ready). The game's own box stays away meanwhile (with the Gamepad UI it stays); its alert sound and the taskbar flash still come."] = "La comprobación de disposición del líder y su tiempo, con Listo y No estoy listo al pasar el ratón (un clic encima: Listo). La caja del juego se mantiene apartada mientras tanto (con la interfaz de mando se queda); su sonido de alerta y el parpadeo de la barra de tareas siguen llegando.", -- draft
	["Threat"] = "Amenaza", -- draft
	["In a group fight, only when it matters: close to pulling your target (\"Ease off\") or with it on you (\"Aggro\"), and for a tank the mobs not on you. The ring is your threat against the pull; point at it for the group's threat on your target."] = "En un combate de grupo, solo cuando importa: cerca de arrancarle el objetivo al tanque («Afloja») o con él encima de ti («Agro»), y para un tanque los enemigos que no están sobre él. El anillo es tu amenaza frente al umbral; señálalo para ver la amenaza del grupo sobre tu objetivo.", -- draft
	["Whispers"] = "Susurros", -- draft
	["A new whisper: the sender in their class colour, the last line and how many are unread. Reply opens their whisper window. Needs Chat's Whisper Popup Window."] = "Un susurro nuevo: el remitente en su color de clase, la última línea y cuántos no se han leído. Responder abre su ventana de susurro. Necesita la Ventana emergente de susurros del chat.", -- draft
	["Hunter Pet"] = "Mascota de cazador", -- draft
	["Your pet is not happy: its face, a ring for its happiness, and Feed Pet on hover (out of combat)."] = "Tu mascota no está contenta: su cara, un anillo para su felicidad y Alimentar a la mascota al pasar el ratón (fuera de combate).", -- draft
	["Auction House"] = "Casa de subastas", -- draft
	["Outbid, sold, won and expired at the auction house, in one list. Click it for the way to the nearest mailbox."] = "Pujas superadas, ventas, victorias y caducadas en la casa de subastas, en una lista. Púlsalo para ver el camino al buzón más cercano.", -- draft
	["Crafting"] = "Fabricación", -- draft
	["A batch you craft: which one of how many, a ring for each item, and Stop on hover."] = "Un lote que fabricas: cuál de cuántos, un anillo por objeto y Detener al pasar el ratón.", -- draft
	["Profession Cooldowns"] = "Tiempos de reutilización de profesión", -- draft
	["A profession cooldown ready again (a transmute, mooncloth, the salt shaker). MelloUI learns it when you open that profession."] = "Un tiempo de reutilización de profesión listo de nuevo (una transmutación, el paño lunar, el salero). MelloUI lo aprende al abrir esa profesión.", -- draft
	["Quest Items"] = "Objetos de misión", -- draft
	["In a quest's objective area, with the quest's item in your bags: the item, a ring for the objective's progress and how many you carry. Click it to use the item (out of combat: it folds away in a fight)."] = "En la zona de un objetivo de misión, con el objeto de la misión en tus bolsas: el objeto, un anillo para el progreso del objetivo y cuántos llevas. Púlsalo para usar el objeto (fuera de combate: se pliega en combate).", -- draft
	["Healer Drinking"] = "Sanador bebiendo", -- draft
	["When you tank a group, between pulls: a healer of your group is drinking, so wait before the next pull. It goes when they stop or a fight starts. The game keeps party mana hidden from addons, so it shows their drinking, not their mana."] = "Cuando tanqueas a un grupo, entre tiradas: un sanador de tu grupo está bebiendo, así que espera antes de la siguiente. Se va cuando deja de beber o empieza un combate. El juego oculta el maná del grupo a los addons, así que muestra que bebe, no su maná.", -- draft
	["Rare Alert"] = "Alerta de raro", -- draft
	["A rare or rare elite nearby, seen on the minimap, as a nameplate, as your target or under the mouse: its face, its name and how far it is, glowing as it comes up. Click its face to target it (out of combat); Lead Me There shows the way to where the minimap has it."] = "Un raro o élite raro cerca, visto en el minimapa, como placa de nombre, como tu objetivo o bajo el ratón: su cara, su nombre y a qué distancia está, brillando al aparecer. Pulsa su cara para seleccionarlo (fuera de combate); Llévame allí muestra el camino a donde lo marca el minimapa.", -- draft
	["Rare Alert Sound"] = "Sonido de alerta de raro", -- draft
	["Play a sound when a rare is spotted."] = "Reproduce un sonido cuando se avista un raro.", -- draft
	["By The Portrait"] = "Junto al retrato", -- draft
	["Bags Almost Full"] = "Bolsas casi llenas", -- draft
	["Remind you when your bags are almost full; it stays, in a fight too, until you make room. Click it for the way to the nearest vendor."] = "Te avisa cuando tus bolsas están casi llenas; se queda, también en combate, hasta que hagas sitio. Púlsalo para ver el camino al vendedor más cercano.", -- draft
	["Free Slots"] = "Casillas libres", -- draft
	["Remind you once this many free bag slots or fewer are left."] = "Te avisa cuando quedan estas casillas de bolsa libres o menos.", -- draft
	["Talent Points"] = "Puntos de talento", -- draft
	["Remind you when you have talent points to spend."] = "Te avisa cuando tienes puntos de talento por gastar.", -- draft
	["Well Fed Ending"] = "Fin de Bien alimentado", -- draft
	["Remind you when Well Fed has two minutes left."] = "Te avisa cuando a Bien alimentado le quedan dos minutos.", -- draft
	["Weapon Poisons & Oils"] = "Venenos y aceites de arma", -- draft
	["Remind you when a poison, an oil or a sharpening stone has run out on a weapon, or has two minutes left, while you carry one to put it back on. It stays until it is back on, in fights too; click it to put it back on (out of combat)."] = "Te avisa cuando un veneno, un aceite o una piedra de afilar se ha acabado en un arma, o le quedan dos minutos, mientras lleves uno para volver a ponerlo. Se queda hasta que vuelve a estar puesto, también en combate; púlsalo para ponerlo (fuera de combate).", -- draft
	["Your Buffs"] = "Tus beneficios", -- draft
	["Remind you when one of your own buffs is missing on you: Arcane Intellect and a mage's armor, Fortitude, Inner Fire and Divine Spirit, Mark of the Wild, a warlock's armor. Only buffs you can cast. It stays until the buff is back, in fights too (the game hides buffs in a fight, so one lost there shows after it); click it to cast (out of combat)."] = "Te avisa cuando te falta uno de tus propios beneficios: Intelecto Arcano y la armadura de un mago, Entereza, Fuego interno y Espíritu divino, Marca de lo Salvaje, la armadura de un brujo. Solo beneficios que puedes lanzar. Se queda hasta que vuelve el beneficio, también en combate (el juego oculta los beneficios en combate, así que uno perdido allí aparece después); púlsalo para lanzarlo (fuera de combate).", -- draft
	["Your Buffs On The Group"] = "Tus beneficios en el grupo", -- draft
	["Remind you when people in your group are missing a buff you can cast (Arcane Intellect and Divine Spirit only on those who use mana); point at it for their names. It stays until they have it, in fights too; click it to cast it on them, one by one (out of combat)."] = "Te avisa cuando a gente de tu grupo le falta un beneficio que puedes lanzar (Intelecto Arcano y Espíritu divino solo a quienes usan maná); señálalo para ver sus nombres. Se queda hasta que lo tengan, también en combate; púlsalo para lanzárselo, uno a uno (fuera de combate).", -- draft
	-- Discard
	["Discard"] = "Desechar", -- draft
	["A button on the bag and loot windows that throws away your cheapest grey or white junk to free a slot (sells it at a vendor)."] = "Un botón en las ventanas de bolsa y de botín que tira tu chatarra gris o blanca más barata para liberar una casilla (la vende en un vendedor).", -- draft
	["Full bags? The cheapest junk makes room, never anything worth keeping."] = "¿Bolsas llenas? La chatarra más barata hace sitio, nunca nada que valga la pena conservar.", -- draft
	["Discard Button"] = "Botón Desechar", -- draft
	["A button on the bag window that frees a slot: it throws away the grey or white junk item worth least (at a vendor it sells it). Never food, drink, potions, scrolls, conjured items, crafting materials, quest items, reagents, ammunition, keys, white gear or anything on your Restock list. A white item asks first."] = "Un botón en la ventana de bolsas que libera una casilla: tira el objeto de chatarra gris o blanco que menos vale (en un vendedor lo vende). Nunca comida, bebida, pociones, pergaminos, objetos conjurados, materiales de fabricación, objetos de misión, componentes, munición, llaves, equipo blanco ni nada de tu lista de Reabastecer. Un objeto blanco pregunta antes.", -- draft
	["Discard Button On Loot"] = "Botón Desechar en el botín", -- draft
	["The same button on the loot window. It frees a slot only when something you are looting is worth more than what it would throw away."] = "El mismo botón en la ventana de botín. Solo libera una casilla cuando algo que estás despojando vale más que lo que tiraría.", -- draft
	["Never Throw Away Items Worth"] = "Nunca tirar objetos que valgan", -- draft
	["In silver: a stack worth this or more is never thrown away (selling it at a vendor still is). 100 silver = 1 gold."] = "En plata: un montón que valga esto o más nunca se tira (venderlo en un vendedor, sí). 100 de plata = 1 de oro.", -- draft
	-- Gains
	["Gains"] = "Ganancias", -- draft
	["Short lines beside your character show what you just gained: a skill point, the items you loot or receive, and what you buy. You can move them in Edit Layout."] = "Líneas cortas junto a tu personaje muestran lo que acabas de ganar: un punto de habilidad, los objetos que despojas o recibes y lo que compras. Puedes moverlas en Editar diseño.", -- draft
	["Every skill point and every new item, told softly beside your character, then gone."] = "Cada punto de habilidad y cada objeto nuevo, contados con suavidad junto a tu personaje y luego desaparecidos.", -- draft
	["Show"] = "Mostrar", -- draft
	["Skill Ups"] = "Subidas de habilidad", -- draft
	["A line when one of your skills goes up: weapon skills, Defense, professions, secondary skills and languages."] = "Una línea cuando sube una de tus habilidades: habilidades de arma, Defensa, profesiones, habilidades secundarias e idiomas.", -- draft
	["Show Skill Values"] = "Mostrar valores de habilidad", -- draft
	["The skill's new value and its cap after its name, such as 57 / 80."] = "El nuevo valor de la habilidad y su tope tras su nombre, como 57 / 80.", -- draft
	["Looted & Received Items"] = "Objetos despojados y recibidos", -- draft
	["A line for each item that comes into your bags: loot, quest rewards, crafted items, mail and trades. Moving items between your bags, the bank and your gear never counts."] = "Una línea por cada objeto que entra en tus bolsas: botín, recompensas de misión, objetos fabricados, correo y comercios. Mover objetos entre tus bolsas, el banco y tu equipo nunca cuenta.", -- draft
	["Bought Items"] = "Objetos comprados", -- draft
	["A line for what you buy from a merchant, buybacks too, marked as bought."] = "Una línea por lo que compras a un mercader, también las recompras, marcada como comprada.", -- draft
	["Junk Items"] = "Chatarra", -- draft
	["Also show junk (grey) items. Off: they are left out."] = "Muestra también la chatarra (gris). Desactivado: se omite.", -- draft
	["Money"] = "Dinero", -- draft
	["A line when your money goes up: loot, quest rewards, sales, mail and trades, with the game's coins. Several gains in a row add up on one line. Spending makes no line."] = "Una línea cuando tu dinero sube: botín, recompensas de misión, ventas, correo y comercios, con las monedas del juego. Varias ganancias seguidas se suman en una línea. Gastar no crea ninguna línea.", -- draft
	["Currencies"] = "Monedas", -- draft
	["A line for the other currencies you gain (honor, tokens, marks), with the currency's own icon."] = "Una línea por las otras monedas que ganas (honor, fichas, marcas), con el icono propio de la moneda.", -- draft
	["Item Names In Quality Colour"] = "Nombres de objeto en color de calidad", -- draft
	["Item names in their quality colour (green, blue, purple) beside the quality gem. Blue and purple read less well over bright ground. Off: the names in the text colour."] = "Nombres de objeto en su color de calidad (verde, azul, morado) junto a la gema de calidad. El azul y el morado se leen peor sobre fondo claro. Desactivado: los nombres en el color del texto.", -- draft
	["Lines"] = "Líneas", -- draft
	["How long each line stays before it fades. Gaining the same skill or item again adds to its line and starts it over."] = "Cuánto tiempo se queda cada línea antes de desvanecerse. Ganar de nuevo la misma habilidad u objeto se suma a su línea y la reinicia.", -- draft
	-- Meter
	["Damage Meter"] = "Medidor de daño", -- draft
	["MelloUI's damage meter in place of the game's: three numbers by every frame (this fight, this run, healing), a race bar for the group in a fight, a summary after it and a Fight History window. The game's own damage meter is switched off while it is on, and comes back as you had it when it is off."] = "El medidor de daño de MelloUI en lugar del del juego: tres números junto a cada marco (este combate, esta incursión, sanación), una barra de carrera para el grupo en combate, un resumen después y una ventana de Historial de combates. El medidor del juego se desactiva mientras este está activo y vuelve como lo tenías cuando se desactiva.", -- draft
	["How the fight went, where you already look."] = "Cómo fue el combate, donde ya estás mirando.", -- draft
	["Your Values"] = "Tus valores", -- draft
	["Three numbers on top of your frame: the sword this fight's damage per second, the hourglass this run's, the cross your healing per second. Live in a fight, the last fight's after it. Move them in Edit Layout (Your Values)."] = "Tres números encima de tu marco: la espada el daño por segundo de este combate, el reloj de arena el de esta incursión, la cruz tu sanación por segundo. En vivo en combate, los del último combate después. Muévelos en Editar diseño (Tus valores).", -- draft
	["Party Values"] = "Valores del grupo", -- draft
	["The same three numbers on top of each party frame. To make room, the game's own Show Party Pets setting is switched on while this is on (the party frames stand a little further apart, and party pets show under them); your own setting comes back when it is off. With raid-style party frames: On Raid-Style Frames."] = "Los mismos tres números encima de cada marco de grupo. Para hacer sitio, el ajuste Mostrar mascotas del grupo del juego se activa mientras esto está activo (los marcos de grupo se separan un poco y las mascotas del grupo aparecen debajo); tu propio ajuste vuelve al desactivarlo. Con marcos de grupo estilo banda: En marcos estilo banda.", -- draft
	["On Raid-Style Frames"] = "En marcos estilo banda", -- draft
	["A small DPS or healing number on the right of each raid-style or raid frame, beside the health. In a fight, players MelloUI cannot tell apart stay empty until it ends. Point at a frame for all three numbers."] = "Un pequeño número de DPS o sanación a la derecha de cada marco estilo banda o de banda, junto a la salud. En combate, los jugadores que MelloUI no puede distinguir quedan vacíos hasta que termina. Señala un marco para ver los tres números.", -- draft
	["Race Bar"] = "Barra de carrera", -- draft
	["In a fight, one line for the group: the top player at its right end with their value, everyone else a class icon at their share of the top, you the bigger icon with the line filled up to you in your class colour. It fades in when the fight starts and out when it ends. The pointer on it lists everyone. Move it in Edit Layout."] = "En combate, una línea para el grupo: el mejor jugador en su extremo derecho con su valor, los demás un icono de clase en su parte respecto al mejor, tú el icono más grande con la línea llena hasta ti en tu color de clase. Aparece al empezar el combate y se desvanece al terminar. El puntero encima lista a todos. Muévela en Editar diseño.", -- draft
	["Race Bar Shows"] = "La barra de carrera muestra", -- draft
	["What the race bar races. Auto: healing while your group role is healer, else damage."] = "Lo que compite en la barra de carrera. Auto: sanación mientras tu función en el grupo sea sanador; si no, daño.", -- draft
	["Auto"] = "Auto", -- draft
	["Damage"] = "Daño", -- draft
	["Healing"] = "Sanación", -- draft
	["Race Bar Pins"] = "Marcas de la barra de carrera", -- draft
	["The most players on the race bar: the best ones, and always you."] = "El máximo de jugadores en la barra de carrera: los mejores, y siempre tú.", -- draft
	["Race Bar Width"] = "Ancho de la barra de carrera", -- draft
	["How wide the race bar is. Also in Edit Layout: right-click the race bar."] = "Lo ancha que es la barra de carrera. También en Editar diseño: clic derecho en la barra de carrera.", -- draft
	["Race Bar Thickness"] = "Grosor de la barra de carrera", -- draft
	["How thick your share is on the race bar's line (its pins and labels keep their size). Also in Edit Layout: right-click the race bar."] = "Lo gruesa que es tu parte en la línea de la barra de carrera (sus marcas y etiquetas mantienen su tamaño). También en Editar diseño: clic derecho en la barra de carrera.", -- draft
	["Fight Summary"] = "Resumen del combate", -- draft
	["After a fight, for a few seconds in the widget column (longer while you point at it): won or lost and its length, your damage, DPS and rank, the ring your share of the group. The pointer on it shows the top five; a click opens the fight in the Fight History."] = "Tras un combate, unos segundos en la columna de widgets (más mientras lo señalas): ganado o perdido y su duración, tu daño, DPS y puesto, el anillo tu parte del grupo. El puntero encima muestra los cinco mejores; un clic abre el combate en el Historial de combates.", -- draft
	["Fight History"] = "Historial de combates", -- draft
	["The Fight History window: every fight of this session, grouped by run, with the damage, healing and your spells of each. It opens from its button in the chat's button column and from the summary. It takes the place of the game's meter windows."] = "La ventana del Historial de combates: cada combate de esta sesión, agrupado por incursión, con el daño, la sanación y tus hechizos de cada uno. Se abre desde su botón en la columna de botones del chat y desde el resumen. Ocupa el lugar de las ventanas del medidor del juego.", -- draft
	["Fights Kept"] = "Combates guardados", -- draft
	["How many fights the history keeps, the oldest dropped first. Kept over a /reload; a new login starts it empty."] = "Cuántos combates guarda el historial; el más antiguo se descarta primero. Se conservan tras un /reload; un inicio de sesión nuevo lo vacía.", -- draft
	-- SwingTimers
	["Swing Timers"] = "Temporizadores de golpe", -- draft
	["A shot bar and a melee bar in MelloUI's look in place of the game's swing timers: each swing and shot counted down beside your weapon's icon, the off hand under the main hand, a wand's shots on the melee bar. The game's own swing timers are switched off while this is on, and come back as you had them when it is off. While the Personal Display shows your swing on its rails (Swing On The Rails), these bars step aside."] = "Una barra de disparo y una barra cuerpo a cuerpo con el aspecto de MelloUI en lugar de los temporizadores de golpe del juego: cada golpe y disparo contado junto al icono de tu arma, la mano izquierda bajo la derecha, los disparos de una varita en la barra cuerpo a cuerpo. Los temporizadores del juego se desactivan mientras esto está activo y vuelven como los tenías al desactivarlo. Mientras la Pantalla personal muestra tus golpes en sus raíles (Golpe en los raíles), estas barras se apartan.", -- draft
	["Every swing and shot at a glance."] = "Cada golpe y cada disparo de un vistazo.", -- draft
	["Shot Bar"] = "Barra de disparo", -- draft
	["The shot bar for a bow, gun, crossbow or thrown weapon while Auto Shot is on: cream, shrinking to the middle while it reloads (you can move), then red, growing from the middle while you aim: stand still, moving holds the shot back."] = "La barra de disparo para un arco, arma de fuego, ballesta o arma arrojadiza mientras Disparo automático está activo: crema, encogiéndose hacia el centro mientras recarga (puedes moverte), luego roja, creciendo desde el centro mientras apuntas: quédate quieto, moverte retiene el disparo.", -- draft
	["Melee Bar"] = "Barra cuerpo a cuerpo", -- draft
	["The melee bar: each swing of your main hand counted down, shrinking to the middle. A wand's shots (Shoot) count down on it too."] = "La barra cuerpo a cuerpo: cada golpe de tu mano derecha en cuenta atrás, encogiéndose hacia el centro. Los disparos de una varita (Disparar) también cuentan en ella.", -- draft
	["Off Hand Bar"] = "Barra de mano izquierda", -- draft
	["A thinner bar under the melee bar for your off-hand weapon's swings, while you carry one."] = "Una barra más fina bajo la barra cuerpo a cuerpo para los golpes de tu arma de mano izquierda, mientras lleves una.", -- draft
	["Seconds"] = "Segundos", -- draft
	["The seconds left, past the bar's right end; on the shot bar Hold and Moving there while you aim. Off: the bars alone."] = "Los segundos restantes, pasado el extremo derecho de la barra; en la barra de disparo, Quieto y En movimiento ahí mientras apuntas. Desactivado: solo las barras.", -- draft
	["Width"] = "Ancho", -- draft
	["How wide the bars are; the weapon's rim hangs left of them and the seconds right of them. Also in Edit Layout (right-click a bar there)."] = "Lo anchas que son las barras; el aro del arma cuelga a su izquierda y los segundos a su derecha. También en Editar diseño (clic derecho en una barra allí).", -- draft
	["Height"] = "Alto", -- draft
	["How tall the bars are; the off hand's is 60 % of it, and the weapon's rim grows with them from 15 on. Also in Edit Layout."] = "Lo altas que son las barras; la de la mano izquierda mide el 60 % de eso, y el aro del arma crece con ellas a partir de 15. También en Editar diseño.", -- draft
	["In Combat: a bar shows in a fight once it swings or shoots, and fades out when the fight ends (the shot bar also when Auto Shot stops). Always: each bar shows while you carry a weapon for it, at rest between swings."] = "En combate: una barra aparece en combate en cuanto golpea o dispara, y se desvanece al terminar el combate (la barra de disparo también cuando se detiene Disparo automático). Siempre: cada barra se ve mientras lleves un arma para ella, en reposo entre golpes.", -- draft
	["In Combat"] = "En combate", -- draft
	["Always"] = "Siempre", -- draft
	-- PartyMarkers
	["Party Markers"] = "Marcadores de grupo", -- draft
	["A class medallion above every party member's friendly nameplate, with a ring in their role's colour. In the open world; inside instances the game keeps friendly nameplates to itself."] = "Un medallón de clase sobre la placa de nombre amistosa de cada miembro del grupo, con un aro del color de su función. En el mundo abierto; dentro de las instancias el juego se reserva las placas de nombre amistosas.", -- draft
	["A class medallion over every party member's head, ringed in their role's colour: the healer, found at a glance."] = "Un medallón de clase sobre la cabeza de cada miembro del grupo, rodeado del color de su función: el sanador, localizado de un vistazo.", -- draft
	["Markers"] = "Marcadores", -- draft
	["Mark"] = "Marcar", -- draft
	["Whose nameplate gets the class medallion above the name."] = "Qué placas de nombre reciben el medallón de clase sobre el nombre.", -- draft
	["Party and raid members"] = "Miembros del grupo y de la banda", -- draft
	["Every friendly player"] = "Todos los jugadores amistosos", -- draft
	["Marker Size"] = "Tamaño del marcador", -- draft
	["The medallion's size above the name."] = "El tamaño del medallón sobre el nombre.", -- draft
	["Height Above The Name"] = "Altura sobre el nombre", -- draft
	["The gap between the name and the medallion."] = "El espacio entre el nombre y el medallón.", -- draft
	["Role Ring"] = "Aro de función", -- draft
	["A coloured ring around the medallion for the member's assigned role: green healer, blue tank, red damage. Only when the group has roles set (the group finder sets them; a party can set them by hand)."] = "Un aro de color alrededor del medallón para la función asignada al miembro: verde sanador, azul tanque, rojo daño. Solo cuando el grupo tiene funciones asignadas (el buscador de grupos las asigna; un grupo puede asignarlas a mano).", -- draft
	["Open world only: inside instances the game keeps friendly nameplates to itself"] = "Solo mundo abierto: dentro de las instancias el juego se reserva las placas de nombre amistosas", -- draft
	-- Sparkles
	["Loot Sparkles"] = "Destellos de botín", -- draft
	["The game's sparkle on quest items you can loot, kept on through its graphics presets, and golden glints over the ore veins and herbs you walk up to: dim out of reach, bright in reach, grey when your skill is too low. The game settings it needs come back as you had them when it is off."] = "El destello del juego en los objetos de misión que puedes despojar, mantenido a pesar de sus preajustes gráficos, y destellos dorados sobre las vetas de mineral y las hierbas a las que te acercas: tenues fuera de alcance, vivos al alcance, grises cuando tu habilidad es demasiado baja. Los ajustes del juego que necesita vuelven como los tenías al desactivarlo.", -- draft
	["What you can loot, at a glance."] = "Lo que puedes despojar, de un vistazo.", -- draft
	["Quest Item Sparkles"] = "Destellos de objetos de misión", -- draft
	["Keeps the game's sparkle on quest items you can loot. It needs the game's outline mode off, which its graphics presets switch back on: held while this is on, given back as you had it when off. Switching this off takes the sparkles away after the next game restart (the client's own; /reload is not enough)."] = "Mantiene el destello del juego en los objetos de misión que puedes despojar. Necesita desactivado el modo de contorno del juego, que sus preajustes gráficos vuelven a activar: retenido mientras esto está activo, devuelto como lo tenías al desactivarlo. Desactivar esto quita los destellos tras el siguiente reinicio del juego (el del cliente; /reload no basta).", -- draft
	["Ore Veins"] = "Vetas de mineral", -- draft
	["Golden glints over the ore vein you walk up to (the game's soft targeting picks the nearest one, within about 15 yards): dim out of reach, bright once you can mine it, grey when your skill is too low."] = "Destellos dorados sobre la veta de mineral a la que te acercas (la selección suave del juego elige la más cercana, a unos 15 metros): tenues fuera de alcance, vivos en cuanto puedes extraerla, grises cuando tu habilidad es demasiado baja.", -- draft
	["Herbs"] = "Hierbas", -- draft
	["The same glints over the herb you walk up to."] = "Los mismos destellos sobre la hierba a la que te acercas.", -- draft
	["Quest Objects"] = "Objetos de misión", -- draft
	["The same glints over a quest object you walk up to. Off by default: the game's own sparkle (Quest Item Sparkles) already marks most of them."] = "Los mismos destellos sobre un objeto de misión al que te acercas. Desactivado por defecto: el destello del juego (Destellos de objetos de misión) ya marca la mayoría.", -- draft
	-- CustomSounds
	["Custom Sounds"] = "Sonidos personalizados", -- draft
	["The interface's sounds replaced by the custom library: iron, leather, parchment and stone for clicks, windows, bags, gear, vendors, whispers and the group finder."] = "Los sonidos de la interfaz sustituidos por la biblioteca personalizada: hierro, cuero, pergamino y piedra para clics, ventanas, bolsas, equipo, vendedores, susurros y el buscador de grupos.", -- draft
	["Iron, leather, parchment and stone. Every click, page, pouch and buckle of the interface, re-recorded."] = "Hierro, cuero, pergamino y piedra. Cada clic, página, bolsa y hebilla de la interfaz, regrabados.", -- draft
	["Sounds"] = "Sonidos", -- draft
	["Clicks"] = "Clics", -- draft
	["Buttons, checkboxes, tabs and scroll arrows: light clicks, a heavy one for Okay/Accept, a latch releasing for Cancel, Quit and abandoning a quest."] = "Botones, casillas, pestañas y flechas de desplazamiento: clics ligeros, uno pesado para Aceptar, un pestillo que se suelta para Cancelar, Salir y abandonar una misión.", -- draft
	["Windows"] = "Ventanas", -- draft
	["A page turn when the character sheet, spell book, quest log or main menu opens, a latch when they close; the spell book's page turns; a quest giver's list and Decline; the bags as a leather pouch opening and closing."] = "Una página que pasa al abrir la hoja de personaje, el libro de hechizos, el registro de misiones o el menú principal, un pestillo al cerrarlos; las páginas del libro de hechizos; la lista de un dador de misiones y Rechazar; las bolsas como una bolsa de cuero que se abre y se cierra.", -- draft
	["Inventory"] = "Inventario", -- draft
	["An item picked up, moved between slots, put down or looted; a rare or better item has its own sound. Silences the game's own pick-up and put-down sounds (the Equipment and Vendor sounds rely on that, and play only while this is on)."] = "Un objeto recogido, movido entre casillas, dejado o despojado; un objeto raro o mejor tiene su propio sonido. Silencia los sonidos de recoger y dejar del juego (los sonidos de Equipo y Vendedor dependen de ello, y solo suenan mientras esto está activo).", -- draft
	["Equipment"] = "Equipo", -- draft
	["Buckles and plate for armour, a steel slide for weapons, jewellery ticks for rings, necks and trinkets; straps loosening when something is taken off."] = "Hebillas y placas para la armadura, un deslizar de acero para las armas, tintineos de joyas para anillos, collares y abalorios; correas aflojándose al quitarse algo.", -- draft
	["Coins on the counter when buying, coins into the pouch when selling (the automatic grey sale too)."] = "Monedas sobre el mostrador al comprar, monedas a la bolsa al vender (la venta automática de lo gris también).", -- draft
	["Social"] = "Social", -- draft
	["A note under the door for a whisper, two knocks for a group invite."] = "Una nota bajo la puerta para un susurro, dos golpes para una invitación de grupo.", -- draft
	["Group Finder"] = "Buscador de grupos", -- draft
	["The ledger for entering a queue or applying to a listing, a strike-through for leaving it, the bell for a group that is ready and for a ready check."] = "El libro de registro al entrar en una cola o solicitar un anuncio, un tachón al salir, la campana para un grupo listo y para una comprobación de disposición.", -- draft
	["The workbench when an item is crafted."] = "El banco de trabajo al fabricar un objeto.", -- draft
	["Quests"] = "Misiones", -- draft
	["The mechanism engaging when a quest is turned in."] = "El mecanismo que encaja al entregar una misión.", -- draft
	["Errors"] = "Errores", -- draft
	["A muted knock for the game's red error messages (\"You can't do that yet\"), at most one every half second; none for a message Error Messages hides."] = "Un golpe sordo para los mensajes de error rojos del juego («Aún no puedes hacer eso»), como mucho uno cada medio segundo; ninguno para un mensaje que oculte Mensajes de error.", -- draft
	["Targets"] = "Objetivos", -- draft
	["An iron sight catching when a target is selected, a latch releasing when it is lost."] = "Una mira de hierro que encaja al seleccionar un objetivo, un pestillo que se suelta al perderlo.", -- draft
	["A seal struck into the record when you level."] = "Un sello estampado en el registro al subir de nivel.", -- draft
	["Loot Coins"] = "Monedas de botín", -- draft
	["Coins into the pouch when money is looted."] = "Monedas a la bolsa al despojar dinero.", -- draft
	["Spell Icons"] = "Iconos de hechizo", -- draft
	["A page lifting when a spell, macro or ability is dragged, the slot latching when it is placed."] = "Una página que se levanta al arrastrar un hechizo, macro o habilidad, la casilla que encaja al colocarlo.", -- draft
	["Map Ping"] = "Señal en el mapa", -- draft
	["An iron pin into the parchment for a minimap ping."] = "Un alfiler de hierro en el pergamino para una señal en el minimapa.", -- draft
	["Scroll Wheel"] = "Rueda del ratón", -- draft
	["One cog notch per mouse-wheel step on any list, window or the chat. The game has no wheel sound; this is an addition."] = "Un diente de engranaje por paso de rueda en cualquier lista, ventana o el chat. El juego no tiene sonido de rueda; esto es un añadido.", -- draft
